/* The few symbols the client's config.c expects from the rest of the client (renderer and transport
 * tables normally generated by CMake, and the global parameter block). Two stub entries each: enough
 * for the renderer/transport option parsers to resolve names, nothing is ever started. */
#include "main.h"
#include "interface/renderer.h"
#include "interface/transport.h"

struct AppParams g_params = { 0 };

static const char * nameOpenGL(void) { return "OpenGL"; }
static const char * nameEGL(void)    { return "EGL"; }

static LG_RendererOps rendererOpenGL = { .getName = nameOpenGL };
static LG_RendererOps rendererEGL    = { .getName = nameEGL    };
LG_RendererOps * LG_Renderers[] = { &rendererOpenGL, &rendererEGL };

static const LG_TransportOps transportLGMP   = { .name = "lgmp"   };
static const LG_TransportOps transportSpice  = { .name = "spice"  };
const LG_TransportOps * LG_Transports[] = { &transportLGMP, &transportSpice };
